void clock_units(const Fixtures& f) {
  // clock-reply.json: probeId 1, receivedMonotonicNs 1000449700000, sentMonotonicNs 1000449900000 (200 us at the source).
  const auto reply = f.server("clock-reply");
  const auto map = [&](std::uint64_t t0, std::uint64_t t3, std::uint64_t probe = 1) { return compute_clock_mapping(reply, probe, CLIENT_CLOCK, t0, t3); };
  const auto exact = map(5000000000ULL, 5000800000ULL);
  check(exact && exact->source_clock_id == SOURCE_CLOCK && exact->client_clock_id == CLIENT_CLOCK && exact->offset_ns == "995449400000" && exact->uncertainty_ns == 300000 && exact->measured_at_client_ns == 5000800000ULL, "exact mapping");
  check(map(5000000000ULL, 5000800001ULL)->offset_ns == "995449399999" && map(5000000000ULL, 5000800001ULL)->uncertainty_ns == 300001, "odd round trip");
  check(map(2000000000000ULL, 2000000800000ULL)->offset_ns == "-999550600000" && map(2000000000000ULL, 2000000800000ULL)->uncertainty_ns == 300000, "negative offset");
  check(map(2000000000000ULL, 2000000800001ULL)->offset_ns == "-999550600001" && map(2000000000000ULL, 2000000800001ULL)->uncertainty_ns == 300001, "negative odd offset rounds down");
  rejects([&] { map(5000000000ULL, 5000100000ULL); }, "negative round trip", "Negative");
  check(!map(5000000000ULL, 6000000001ULL), "late reply discarded"); check(map(5000000000ULL, 6000000000ULL)->measured_at_client_ns == 6000000000ULL, "deadline inclusive");
  rejects([&] { map(5000000000ULL, 4999999999ULL); }, "reply before probe", "before its probe");
  rejects([&] { map(5000000000ULL, 5000800000ULL, 2); }, "mismatched probe", "mismatch");
  rejects([&] { compute_clock_mapping(f.server("welcome"), 1, CLIENT_CLOCK, 0, 1); }, "non-reply message");
  rejects([&] { compute_clock_mapping(reply, 1, "not-a-clock", 5000000000ULL, 5000800000ULL); }, "client clock UUID", "mismatch");
  const auto with_times = [&](const std::string& received, const std::string& sent, const std::string& capture) {
    auto m = reply; field(field(m.wire, "capture"), "monotonicNs") = text_json(capture);
    field(field(m.wire, "data"), "receivedMonotonicNs") = text_json(received); field(field(m.wire, "data"), "sentMonotonicNs") = text_json(sent); return m;
  };
  // 2 s at the client cannot contain 3 s at the source: impossible, not merely late.
  rejects([&] { compute_clock_mapping(with_times("997449900000", "1000449900000", "1000450000000"), 1, CLIENT_CLOCK, 5000000000ULL, 7000000000ULL); }, "negative round trip before lateness", "Negative");
  const auto high = compute_clock_mapping(with_times("18446744073709551615", "18446744073709551615", "18446744073709551615"), 1, CLIENT_CLOCK, 0, 0);
  check(high && high->offset_ns == "18446744073709551615" && high->uncertainty_ns == 0 && high->measured_at_client_ns == 0, "maximum positive offset");
  const auto low = compute_clock_mapping(with_times("0", "0", "18446744073709551615"), 1, CLIENT_CLOCK, u64_max, u64_max);
  check(low && low->offset_ns == "-18446744073709551615" && low->uncertainty_ns == 0 && low->measured_at_client_ns == u64_max, "maximum negative offset");
  check(is_clock_mapping_current(*exact, SOURCE_CLOCK, CLIENT_CLOCK), "current mapping");
  check(!is_clock_mapping_current(*exact, "30000000-0000-4000-8000-000000000002", CLIENT_CLOCK), "source clock change invalidates");
  check(!is_clock_mapping_current(*exact, SOURCE_CLOCK, "60000000-0000-4000-8000-000000000002"), "client clock change invalidates");
}

